                myNodes[size] = null;
                myNodes[0] = lastNode;
                lastNode.index = 0;
                down(0);
            } else {
                myNodes[0] = null;
            }
            return result;
        }

        @Override
        public void clear() {
            for (int i = 0; i < size; i++) {
                myNodes[i] = null;
            }
            size = 0;
        }

